import { expect, expectStatus, test } from "../../fixtures";

test("once a vendor is sent back, its other documents cannot be decided", { tag: "@LIF-03" }, async ({ apiAs, factory }) => {
  // Arrange: a vendor in review, and the reviewer sends back its W-9.
  const { extractions, documents } = await factory.vendorInReview();
  const reviewer = await apiAs("reviewer");
  const rejected = await reviewer.post(`/api/extractions/${extractions.w9.id}/decision`, {
    data: { decision: "reject", note: "Please re-sign the W-9" },
  });
  await expectStatus(rejected, 200);

  // Act: the reviewer tries to approve the contract extraction.
  const response = await reviewer.post(`/api/extractions/${extractions.contract.id}/decision`, {
    data: { decision: "approve" },
  });

  // Assert: refused with the vendor-not-in-review code, and the stored decision is unchanged.
  const body = await expectStatus(response, 409);
  expect(body.error.code).toBe("vendor_not_in_review");
  expect((await factory.extraction(documents.contract.id)).status).toBe("pending_review");
});
